$passed=$failed=0;
function same($expected,$actual) { if($expected!==$actual) throw new RuntimeException('Expected '.var_export($expected,true).' got '.var_export($actual,true)); }
function check($value) { if(!$value) throw new RuntimeException('Assertion failed'); }
function test($name,$run) { global $passed,$failed; try { $run(); $passed++; echo 'PASS '.$name.PHP_EOL; } catch(Throwable $error) { $failed++; echo 'FAIL '.$name.': '.$error->getMessage().PHP_EOL.$error->getTraceAsString().PHP_EOL; } }
function raises($class,$run) { try { $run(); } catch(Throwable $error) { if($error instanceof $class) return; throw $error; } throw new RuntimeException('Expected '.$class); }
