        $schema='mystep_review_'.bin2hex(random_bytes(6));
        $admin->query('CREATE DATABASE `'.$schema.'` CHARACTER SET utf8mb4');
        $a=$b=$sqlCache=null;
        try {
            $settings['name']=$schema;
            $a=new ReviewMySQL($settings['host'],$settings['user'],$settings['password'],'utf8mb4'); $a->connect(false,$schema);
            $b=new ReviewMySQL($settings['host'],$settings['user'],$settings['password'],'utf8mb4'); $b->connect(false,$schema);
            $shared=new myCache_File(directory('mysql-cache'));$a->setCache($shared);$b->setCache($shared);
            $a->query('CREATE TABLE items (id INT PRIMARY KEY, value TEXT, category VARCHAR(30), nullable TEXT, bin MEDIUMBLOB, flag INT, ratio DOUBLE) ENGINE=InnoDB');
            test('MySQL prepared values preserve SQL-looking text without execution',function()use($a){$value="x'); DROP TABLE items; -- 中文";same(1,$a->execute('INSERT INTO items(id,value,category) VALUES(?,?,?)',[1,$value,'a']));same($value,$a->fetchValue('SELECT value FROM items WHERE id=?',[1]));same(1,$a->fetchValue('SELECT COUNT(*) FROM items'));});
            test('MySQL prepared types preserve binary null bool and floating values',function()use($a){$binary="\0\xff\\'";same(1,$a->execute('INSERT INTO items(id,value,bin,nullable,flag,ratio,category) VALUES(?,?,?,?,?,?,?)',[2,'typed',$binary,null,true,1.25,'a']));same(['bin'=>$binary,'nullable'=>null,'flag'=>1,'ratio'=>1.25],$a->fetchOne('SELECT bin,nullable,flag,ratio FROM items WHERE id=?',[2]));});
            test('MySQL prepared blob streams preserve large binary data',function()use($a){$data=str_repeat("binary\0\xff",16384);$stream=fopen('php://temp','w+b');fwrite($stream,$data);rewind($stream);try{same(1,$a->execute('INSERT INTO items(id,value,bin,category) VALUES(?,?,?,?)',[3,'stream',$stream,'b']));same($data,$a->fetchValue('SELECT bin FROM items WHERE id=?',[3]));}finally{fclose($stream);}});
            test('MySQL parameter mismatches fail without damaging the connection',function()use($a){raises(InvalidArgumentException::class,function()use($a){$a->execute('SELECT ?',[]);});raises(InvalidArgumentException::class,function()use($a){$a->execute('SELECT ?',[1],'invalid');});same(1,$a->fetchValue('SELECT 1'));});
            test('MySQL count preserves DISTINCT GROUP HAVING and UNION semantics',function()use($a){same('2',$a->count('SELECT DISTINCT category FROM items LIMIT 1'));same('1',$a->count('SELECT category, COUNT(*) AS total FROM items GROUP BY category HAVING total>1 LIMIT 1'));same('2',$a->count("SELECT 'a' UNION SELECT 'b' LIMIT 1"));});
            test('MySQL caches missing rows and NULL scalars without extra queries',function()use($a){$counter=new ReflectionProperty('MySQL','count');$counter->setAccessible(true);same(false,$a->record('SELECT id FROM items WHERE id=999'));$count=$counter->getValue($a);same(false,$a->record('SELECT id FROM items WHERE id=999'));same($count,$counter->getValue($a));same(null,$a->result('SELECT nullable FROM items WHERE id=2'));$count=$counter->getValue($a);same(null,$a->result('SELECT nullable FROM items WHERE id=2'));same($count,$counter->getValue($a));});
            test('MySQL commit invalidates results cached by another connection',function()use($a,$b){$sql='SELECT value FROM items WHERE id=1';$before=$b->result($sql);$a->begin();$a->execute('UPDATE items SET value=? WHERE id=?',['committed',1]);same('committed',$a->result($sql));same($before,$b->result($sql));$a->commit();same('committed',$b->result($sql));});
            test('MySQL rollback never publishes uncommitted results',function()use($a,$b){$sql='SELECT value FROM items WHERE id=1';$a->begin();$a->execute('UPDATE items SET value=? WHERE id=?',['rolled-back',1]);same('rolled-back',$a->result($sql));$a->rollback();same('committed',$a->result($sql));same('committed',$b->result($sql));});
            test('MySQL nested transaction savepoints preserve outer work',function()use($a){$a->transaction(function($tx){$tx->execute('UPDATE items SET value=? WHERE id=?',['outer',1]);raises(RuntimeException::class,function()use($tx){$tx->transaction(function($nested){$nested->execute('UPDATE items SET value=? WHERE id=?',['inner',1]);throw new RuntimeException('rollback inner');});});same('outer',$tx->fetchValue('SELECT value FROM items WHERE id=?',[1]));});same('outer',$a->result('SELECT value FROM items WHERE id=1'));});
            test('MySQL raw transaction controls keep shared cache coherent',function()use($a,$b){$a->query('BEGIN');$a->execute('UPDATE items SET value=? WHERE id=?',['raw',1]);same('outer',$b->result('SELECT value FROM items WHERE id=1'));$a->query('COMMIT');same('raw',$b->result('SELECT value FROM items WHERE id=1'));});
            test('MySQL proxy and query wrapper honor transaction boundaries',function()use($settings,$shared){$proxy=new myDb('ReviewMySQL',$settings['host'],$settings['user'],$settings['password'],'utf8mb4');$proxy->connect(false,$settings['name']);$proxy->setCache($shared);$old=$GLOBALS['db']??null;$GLOBALS['db']=$proxy;try{$cache=new myCache('File',directory('mysql-wrapper'),0);$sql='SELECT value FROM items WHERE id=1';same('raw',$cache->getData($sql,'result'));$proxy->transaction(function($tx)use($cache,$sql){$tx->execute('UPDATE items SET value=? WHERE id=?',['wrapped',1]);same('wrapped',$cache->getData($sql,'result'));});same('wrapped',$cache->getData($sql,'result'));}finally{$proxy->close();$GLOBALS['db']=$old;}});
            test('MySQL session values and same-named temporary tables stay connection-local',function()use($a,$b){$a->query('SET @probe=1');$b->query('SET @probe=2');same('1',$a->result('SELECT @probe'));same('2',$b->result('SELECT @probe'));foreach([[$a,'a'],[$b,'b']] as $pair){$pair[0]->query('CREATE TEMPORARY TABLE local_values(value TEXT)');$pair[0]->execute('INSERT INTO local_values VALUES(?)',[$pair[1]]);}same('a',$a->result('SELECT value FROM local_values'));same('b',$b->result('SELECT value FROM local_values'));});
            test('MySQL lost connection retries a safe read with the selected database',function()use($a,$admin,$schema){$a->reconnect(false,$schema);$property=new ReflectionProperty('MySQL','connect');$property->setAccessible(true);$killed=$property->getValue($a)->thread_id;check($admin->query('KILL CONNECTION '.(int)$killed));$deadline=microtime(true)+1;while((int)$admin->query('SELECT COUNT(*) FROM information_schema.PROCESSLIST WHERE ID='.(int)$killed)->fetch_row()[0]!==0 && microtime(true)<$deadline)usleep(1000);same(1,$a->query('SELECT DATABASE()'));same($schema,$a->getRS(1)[0]);$a->free();check($property->getValue($a)->thread_id!==$killed);});
            test('MySQL lost connection never automatically replays writes',function()use($a,$admin,$schema){$property=new ReflectionProperty('MySQL','connect');$property->setAccessible(true);$killed=$property->getValue($a)->thread_id;check($admin->query('KILL CONNECTION '.(int)$killed));$deadline=microtime(true)+1;while((int)$admin->query('SELECT COUNT(*) FROM information_schema.PROCESSLIST WHERE ID='.(int)$killed)->fetch_row()[0]!==0 && microtime(true)<$deadline)usleep(1000);raises(RuntimeException::class,function()use($a){$a->execute('UPDATE items SET value=? WHERE id=?',['must-not-retry',1]);});$a->reconnect(false,$schema);same('wrapped',$a->fetchValue('SELECT value FROM items WHERE id=?',[1]));});
            test('MySQL cache adapter resolves short name and preserves binary payloads',function()use($settings){$cache=new myCache('MySQL',$settings,0);foreach([null,false,0,'',[],"\0\xff中文"] as $key=>$value){check($cache->set('typed-'.$key,$value));same($value,$cache->get('typed-'.$key));}$cache->remove('typed-0');same(false,$cache->get('typed-0'));});
        } finally {
            if($a) $a->close(); if($b) $b->close();
            $admin->query('DROP DATABASE `'.$schema.'`'); $admin->close();
        }
    }

} finally { myFile::del($scratch); myFile::del(sys_get_temp_dir().'/mystep-cache-'.substr(hash('sha256', ROOT),0,16)); }
echo "Passed: $passed; Failed: $failed\n";exit($failed?1:0);
